input.command:
cd /tmp/opencode && python3 -c "
import json
j={r['sid'] for r in json.load(open('wiki_rows.json')) if r['sid']}
l={r['sid'] for r in json.load(open('db_live.json'))}
b={r['sid'] for r in json.load(open('db_backup.json'))}
print('union all:',len(j|l|b))
print('jsonl',len(j),'live',len(l),'backup',len(b))
print('live only (not jsonl):',len(l-j),'backup only:',len(b-j-l))
print('sum raw:',len(j)+len(l)+len(b))
"

